Let $(A_i,\phi_i)$ be an AH system with diagonal maps. Let $A$ be the limit algebra, and let $D$ be its canonical diagonal subalgebra. Then the following properties are equivalent:
\begin{enumerate}
\item $A$ is $\mathcal Z$-absorbing,
\item $\mathrm{mdim}(A_i, \phi_i) = 0$.


\end{enumerate}

\label{prop:allocated-bundle-embedding}
Suppose that $r\geq0$ is a comparison bound for $A$, with normalized
traces and unnormalized matrix traces.  Let $s=1,\ldots,S$ index a
finite open castle with nonempty finite shapes $F_s\subset\Gamma$ and
bases $B_s\subset X$: all the sets $T_aB_s$, for $a\in F_s$ and
$1\leq s\leq S$, are pairwise disjoint.

For each $s$, fix positive integers $g_s,R_s$, a compact set
$K_s\subset B_s$, and continuous maps
\[
 F_{s,j}:X\longrightarrow[-1,1]^t,\qquad 1\leq j\leq g_s.
\]
Assume that
\begin{equation}
\label{eq:castle-tracial-rank-gap}
 \sum_{s=1}^S(R_s-pg_s)\mu(B_s)>r
 \quad\text{for every invariant probability measure }\mu.
\end{equation}

Then there is a finite set $K\subset\Gamma$ with the following
property.  Let $F\subset\Gamma$ be any nonempty finite window, and
suppose that there are $n\geq1$ continuous maps
$f_\nu:X\to[-1,1]^t$, continuous weights
$w_\nu:X\to[0,1]$, and locally constant maps
\[
 \ell_\nu:\{w_\nu>0\}\longrightarrow
 \{(s,v,j):1\leq s\leq S,\ v\in F,\ 1\leq j\leq g_s\}
 \qquad(1\leq\nu\leq n)
\]
such that:
\begin{enumerate}
\item whenever $\ell_\nu(x)=(s,v,j)$,
\begin{equation}
\label{eq:allocated-slot-agreement}
 T_vx\in K_s,\qquad f_\nu(x)=F_{s,j}(T_vx);
\end{equation}
\item for every $x$, the labels $\ell_\nu(x)$ of the slots with
$w_\nu(x)>0$ are pairwise distinct;
\item for some $\beta\geq0$,
\begin{equation}
\label{eq:allocated-slot-exception-count}
 \#\{\nu:w_\nu(x)<1\}\leq\beta n\qquad(x\in X).
\end{equation}
\end{enumerate}
Let $q_F$ be an integer such that
\begin{equation}
\label{eq:allocated-output-rank-count}
 \sum_{s=1}^S R_s\#\{v\in KF:T_vx\in B_s\}\leq q_F
 \qquad(x\in X).
\end{equation}
Put $f=(f_1,\ldots,f_n)$ and
\[
 \mathcal T_F=\{(x,z)\in X\times Z_{an}(t,n):
                  f(x)-z\in L^n\}.
\]
In place of Equation~\eqref{eq:allocated-slot-exception-count}, it
suffices to assume the weaker condition
\begin{equation}
\label{eq:allocated-slot-exception-count-on-locus}
 \#\{\nu:z_\nu=0,\ w_\nu(x)<1\}\leq\beta n
 \qquad((x,z)\in\mathcal T_F).
\end{equation}
The rank-$pn$ bundle
\[
 \mathcal E_F=\bigoplus_{\nu=1}^n
           \mathcal H_{f_\nu(x)-z_\nu}
 \longrightarrow\mathcal T_F
\]
admits one continuous bundle monomorphism into the trivial bundle of
rank
\begin{equation}
\label{eq:allocated-bundle-target-rank}
 q_F+2p\lceil(a+\beta)n\rceil.
\end{equation}
In particular, the hypothesis of the external torus-compression
theorem holds whenever this integer is strictly less than $2pn$.

One may take
\begin{equation}
\label{eq:castle-output-packing-bound}
 q_F=\left\lfloor
       \max_{1\leq s\leq S}\frac{R_s}{|F_s|}\,
       \left|\left(\bigcup_{s=1}^SF_s\right)KF\right|
      \right\rfloor.
\end{equation}
The cutoffs, Fourier witness, and its propagation set $K$ are chosen
before $F$, $n$, and the slot allocation.
